import * as z from 'zod/mini';

/**
 * Creates a string schema with a deprecation warning.
 * Logs a warning when this schema is validated against.
 */
function deprecatedString(message: string): z.ZodMiniType<string> {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- check function receives ParsePayload
  return z.string().check((_payload: any) => {
    console.warn(`DEPRECATION WARNING: ${message}`);
  }) as z.ZodMiniType<string>;
}

const storeAsKey = z.string().check(z.minLength(1));

const resourceResolverSchema = z.object({ $resource: z.string() });
const attributeResolverSchema = z.object({ $attribute: z.string() });
const storeResolverSchema = z.object({ $store: z.string() });

/**
 * A resource statement that will be resolved to a value. Example:
 * ```
 * { $resource: "myResource" }
 * ```
 * becomes `"resource value"`
 */
export type ResourceStatement = z.infer<typeof resourceResolverSchema>;

/**
 * An attribute statement that will be resolved to a value. Example:
 * ```
 * { $attribute: "myAttribute" }
 * ```
 * becomes `"attribute value"`
 */
export type AttributeStatement = z.infer<typeof attributeResolverSchema>;

/**
 * A store statement that reads from the unified store via dot-path. Example:
 * ```
 * { $store: "selectedSurface.meta.showVoiceEducation" }
 * ```
 * becomes `true`
 */
export type StoreStatement = z.infer<typeof storeResolverSchema>;

const configPrimitiveSchema = z.union([z.string(), z.number(), z.boolean(), z.null(), z.undefined()]);

/**
 * A primitive value (string, number, boolean, null, undefined)
 */
type ConfigPrimitive = z.infer<typeof configPrimitiveSchema>;

/**
 * A case in a switch statement. Because of the generic type, we'll
 * manually type this condition out.
 */
export type SwitchCase<T> = {
  condition: ResolverStatements<ConfigPrimitive> | ConfigPrimitive;
  value: ResolverStatements<T> | T;
};

/**
 * A switch statement. Example:
 * ```
 * {
 *   $switch: [
 *     { condition: true, value: "on" },
 *     { condition: false, value: "off" },
 *     "default",
 *   ],
 * }
 * ```
 * becomes `"on"`
 */
export type SwitchStatement<T> = {
  $switch: (SwitchCase<T> | string)[];
};

/**
 * Union of all resolver statement types used in raw configurations.
 * Generic over T to preserve the value type of `SwitchStatement<T>`.
 */
export type ResolverStatements<T> = ResourceStatement | AttributeStatement | StoreStatement | SwitchStatement<T>;

/**
 * This represents the type that can be used as a CONDITION in a
 * a switch statement. The `value` part has a stricter type.
 */
const resolvableConfigPrimitiveSchema = z.union([
  configPrimitiveSchema,
  resourceResolverSchema,
  attributeResolverSchema,
  storeResolverSchema,
  z.object({
    $switch: z.array(
      z.union([
        z.object({
          get condition() {
            return resolvableConfigPrimitiveSchema;
          },
          get value() {
            return resolvableConfigPrimitiveSchema;
          }
        }),
        z.string()
      ])
    )
  })
]);

export const CLIENT_ACTION_NAMES = ['voice', 'chat', 'avatar', 'place', 'moments-ip'] as const;

export const ClientActionNameSchema = z.literal(CLIENT_ACTION_NAMES);

export const SubmissionTargetSchema = z
  .discriminatedUnion('type', [
    z.strictObject({
      type: z.literal('default')
    }),
    z.strictObject({
      type: z.literal('clientAction'),
      name: ClientActionNameSchema
    })
  ])
  .register(z.globalRegistry, { luauName: 'SubmissionTarget' });

export type ClientActionName = z.infer<typeof ClientActionNameSchema>;
export type SubmissionTarget = z.infer<typeof SubmissionTargetSchema>;

/**
 * @see makeResolvable for more info.
 *
 * Conditional Zod type driven by the `Raw` boolean literal.
 *
 * - `Resolvable<T, false>` = `z.ZodMiniType<z.infer<T>>`         (precise base type)
 * - `Resolvable<T, true>`  = `z.ZodMiniType<z.infer<T> | ResolverStatements>`
 */
type Resolvable<T extends z.ZodMiniType, Raw extends boolean> = z.ZodMiniType<
  Raw extends true ? z.infer<T> | ResolverStatements<z.infer<T>> : z.infer<T>
>;

/**
 * We have two types of schemas:
 * - Raw: allows for resolver statements
 * - Normalized: does not allow for resolver statements
 *
 * But we only want to define our core structure once, so we'll need a bit of TS
 * magic to make that one structure produce two different types.
 *
 * This function Wraps a Zod schema to allow "Resolver" statements (dynamic
 * runtime values).
 *
 * When `isRaw` is `false`, returns the schema with its precise output type
 * preserved. When `isRaw` is `true`, creates a recursive union that also
 * accepts resolver statements (`$resource`, `$attribute`, `$store`,
 * `$switch`).
 *
 * The generic `Raw extends boolean` preserves the literal `true` / `false` so
 * that the conditional return type `Resolvable<T, Raw>` resolves to different
 * types at each call site:
 *
 * ```ts
 * makeResolvable(z.string(), false) // → z.ZodMiniType<string>
 * makeResolvable(z.string(), true)  // → z.ZodMiniType<string | ResolverStatements>
 * ```
 */
const makeResolvable = <T extends z.ZodMiniType, Raw extends boolean>(schema: T, isRaw: Raw): Resolvable<T, Raw> => {
  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
  if (!isRaw) return schema as Resolvable<T, Raw>;

  // Resolvable schema wrapper for T-typed values
  const resolvableSchema = z.union([
    schema,
    resourceResolverSchema,
    attributeResolverSchema,
    storeResolverSchema,
    z.object({
      $switch: z.array(
        z.union([
          z.object({
            condition: resolvableConfigPrimitiveSchema,
            get value() {
              return resolvableSchema;
            }
          }),
          // Default case: a plain string at the end of the $switch array
          // TODO: [future] we should consider not changing this to either
          // not be allowed, or use the proper type (schema in this case) (abech).
          deprecatedString(
            "Using plain string in $switch array is deprecated. Use an object with 'condition' and 'value' properties instead. For default case at end use { condition: true, value: <default value> }."
          )
        ])
      )
    })
  ]);

  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
  return resolvableSchema as Resolvable<T, Raw>;
};

/**
 * Schema factory for the abuse report configuration.
 *
 * @param isRaw When false, produces the normalized (UI) schema.
 *              When true, produces the raw (JSON-resolvable) schema.
 */
export const createConfigSchema = <Raw extends boolean>(isRaw: Raw) => {
  const r = <S extends z.ZodMiniType>(s: S) => makeResolvable(s, isRaw);

  const linkWrapperConfigSchema = z.object({
    type: z.literal('link'),
    href: r(z.string()),
    openInNewWindow: z.optional(r(z.boolean())),
    rel: z.optional(z.string()),
    className: z.optional(z.string())
  });

  const strongWrapperConfigSchema = z.object({
    type: z.literal('strong'),
    className: z.optional(z.string())
  });

  const wrapperConfigSchema = z.union([linkWrapperConfigSchema, strongWrapperConfigSchema]);

  // Inner translate schema for use as a nested $translate param value.
  // Supports resolvable $translate key and resolvable string params (one level of nesting).
  // The UI translate function handles arbitrary depth at runtime via its own recursion.
  const nestedTranslateInputSchema = z.object({
    $translate: r(z.string()),
    params: z.optional(z.record(z.string(), r(z.string())))
  });

  const translateInputSchema = z.object({
    $translate: r(z.string()),
    params: z.optional(z.record(z.string(), z.union([r(z.string()), nestedTranslateInputSchema]))),
    wrappers: z.optional(z.record(z.string(), wrapperConfigSchema))
  });

  const text = r(z.union([translateInputSchema, z.string()]).register(z.globalRegistry, { luauName: 'TextValue' }));

  const inlineAlertSchema = z
    .object({
      type: r(z.enum(['success', 'error', 'warning', 'info'])),
      title: text,
      subtitle: z.optional(text)
    })
    .register(z.globalRegistry, { luauName: 'InlineAlertValue' });

  const nextSimpleSchema = z
    .union([
      z.string(),
      z.object({
        type: z.literal('goto'),
        nodeId: z.string(),
        replace: z.optional(z.boolean()),
        inlineAlert: z.optional(inlineAlertSchema)
      }),
      z.object({ type: z.literal('close'), inlineAlert: z.optional(inlineAlertSchema) }),
      z.object({ type: z.literal('reset'), inlineAlert: z.optional(inlineAlertSchema) }),
      z.object({
        type: z.literal('link'),
        href: r(z.string()),
        openInNewWindow: z.optional(r(z.boolean())),
        inlineAlert: z.optional(inlineAlertSchema)
      })
    ])
    .register(z.globalRegistry, { luauName: 'NextSimpleValue' });

  const nextSubmitFormSchema = z.object({
    type: z.literal('submitForm'),
    onSuccess: nextSimpleSchema,
    onFailure: z.optional(nextSimpleSchema)
  });

  const next = r(
    z.union([nextSimpleSchema, nextSubmitFormSchema]).register(z.globalRegistry, { luauName: 'NextValue' })
  );

  const listItemSchema = z
    .object({
      id: z.string(),
      label: text,
      description: z.optional(text),
      leading: z.optional(z.string()),
      meta: z.optional(z.record(z.string(), r(configPrimitiveSchema)))
    })
    .register(z.globalRegistry, { luauName: 'ListItem' });

  const loadDescriptorSchema = z
    .object({
      $load: z.string(),
      params: z.optional(z.record(z.string(), r(z.string())))
    })
    .register(z.globalRegistry, { luauName: 'LoadDescriptor' });

  const previewSchema = z
    .discriminatedUnion('type', [
      z.object({
        type: z.literal('user'),
        id: r(z.string()),
        displayName: z.optional(r(z.string())),
        username: z.optional(r(z.string()))
      }),
      z.object({
        type: z.literal('chat'),
        text
      }),
      z.object({
        type: z.literal('experience'),
        id: r(z.string()),
        title: z.optional(r(z.string()))
      })
    ])
    .register(z.globalRegistry, { luauName: 'PreviewValue' });

  const blockToggleSchema = z.object({
    label: text,
    description: z.optional(text),
    errorLabel: text,
    userId: r(z.string()),
    blockedSnackbarMessage: z.optional(text),
    unblockedSnackbarMessage: z.optional(text)
  });

  const muteToggleSchema = z.object({
    label: text,
    description: z.optional(text),
    errorLabel: text,
    userId: r(z.string()),
    mutedSnackbarMessage: z.optional(text),
    unmutedSnackbarMessage: z.optional(text)
  });

  const helplineSchema = z.object({
    buttonText: text,
    heading: text,
    href: r(z.string())
  });

  const subtitleSchema = z
    .object({
      leading: z.optional(r(z.string())),
      text
    })
    .register(z.globalRegistry, { luauName: 'SubtitleValue' });

  const trailingAccessorySchema = z
    .discriminatedUnion('type', [
      z.object({ type: z.literal('voiceSpeakingIndicator') }),
      z.object({ type: z.literal('recentlyLeftIndicator'), text })
    ])
    .register(z.globalRegistry, { luauName: 'TrailingAccessoryValue' });

  return z.object({
    version: z.literal(4),
    name: z.string().check(z.minLength(1)),
    startNode: z.optional(r(z.string())),
    resources: z.record(
      z.string(),
      z.object({
        type: z.literal('listItem'),
        value: z.array(r(listItemSchema))
      })
    ),
    display: z.object({
      title: z.optional(text),
      closeButtonLabel: text,
      titleDisclosure: z.optional(
        r(
          z.object({
            ariaLabel: z.optional(text),
            tooltipTitle: text,
            tooltipText: text,
            buttonLabel: z.optional(text),
            openByDefault: z.optional(r(z.boolean())),
            closeButtonLabel: text
          })
        )
      )
    }),
    nodes: z.record(
      z.string(),
      z
        .discriminatedUnion('type', [
          // ListNode
          z.object({
            type: z.literal('list'),
            title: text,
            subtitle: z.optional(r(subtitleSchema)),
            items: z.union([r(z.array(r(listItemSchema))), loadDescriptorSchema]),
            storeAs: storeAsKey,
            storeAsSamples: z.optional(z.array(listItemSchema)),
            variant: z.optional(z.enum(['chevron', 'radio'])),
            nextButtonText: text,
            errorText: text,
            retryButtonText: text,
            emptyText: z.optional(text),
            required: z.optional(r(z.boolean())),
            next,
            eyebrow: z.optional(text),
            footerItems: z.optional(r(z.array(r(listItemSchema))))
          }),
          // CommentNode
          z.object({
            type: z.literal('comment'),
            title: text,
            subtitle: z.optional(r(subtitleSchema)),
            storeAs: storeAsKey,
            textAreaLabel: z.optional(text),
            textAreaAriaLabel: z.optional(text),
            maxLength: z.optional(r(z.number())),
            helperText: z.optional(text),
            placeholder: text,
            nextButtonText: text,
            next,
            eyebrow: z.optional(text),
            footerItems: z.optional(r(z.array(r(listItemSchema))))
          }),
          // ConfirmationNode
          z.object({
            type: z.literal('confirmation'),
            title: text,
            subtitle: z.optional(r(subtitleSchema)),
            message: text,
            blockToggle: z.optional(r(blockToggleSchema)),
            helpline: z.optional(r(helplineSchema)),
            nextButtonText: text,
            next,
            eyebrow: z.optional(text),
            footerItems: z.optional(r(z.array(r(listItemSchema))))
          }),
          // ParagraphNode
          z.object({
            type: z.literal('paragraph'),
            title: text,
            subtitle: z.optional(r(subtitleSchema)),
            paragraph: text,
            nextButtonText: text,
            next,
            eyebrow: z.optional(text),
            footerItems: z.optional(r(z.array(r(listItemSchema))))
          }),
          // ReviewNode — summary/review screen with preview and detail pairs
          z.object({
            type: z.literal('review'),
            title: text,
            subtitle: z.optional(r(subtitleSchema)),
            preview: z.optional(r(previewSchema)),
            details: r(z.array(r(z.object({ heading: text, text: text })))),
            nextButtonText: text,
            next,
            eyebrow: z.optional(text),
            footerItems: z.optional(r(z.array(r(listItemSchema))))
          }),
          // InExpChatSelectionNode — in-experience chat message selection
          z.object({
            type: z.literal('inExpChatSelection'),
            title: text,
            items: z.union([r(z.array(r(listItemSchema))), loadDescriptorSchema]),
            storeAs: storeAsKey,
            storeAsSamples: z.optional(z.array(listItemSchema)),
            required: z.optional(r(z.boolean())),
            nextButtonText: text,
            errorText: text,
            retryButtonText: text,
            emptyText: text,
            reportMessageNotShownText: text,
            next,
            eyebrow: z.optional(text),
            footerItems: z.optional(r(z.array(r(listItemSchema))))
          }),
          // InExpUserSelectionNode — in-experience inline user selection with trailing accessories
          z.object({
            type: z.literal('inExpUserSelection'),
            title: text,
            subtitle: z.optional(r(subtitleSchema)),
            items: z.union([r(z.array(r(listItemSchema))), loadDescriptorSchema]),
            storeAs: storeAsKey,
            storeAsSamples: z.optional(z.array(listItemSchema)),
            variant: z.optional(z.enum(['chevron', 'radio'])),
            trailingAccessories: z.optional(r(z.array(trailingAccessorySchema))),
            nextButtonText: text,
            errorText: text,
            retryButtonText: text,
            emptyText: z.optional(text),
            required: z.optional(r(z.boolean())),
            next,
            eyebrow: z.optional(text),
            footerItems: z.optional(r(z.array(r(listItemSchema))))
          }),
          // InExpSceneSelectionNode — in-experience 3D scene selection
          z.object({
            type: z.literal('inExpSceneSelection'),
            title: text,
            loadingText: z.optional(text),
            errorText: z.optional(text),
            nextOnFailure: z.optional(nextSimpleSchema),
            next,
            eyebrow: z.optional(text),
            footerItems: z.optional(r(z.array(r(listItemSchema))))
          }),
          // InExpConfirmationNode — in-experience confirmation with mute/block toggles
          z.object({
            type: z.literal('inExpConfirmation'),
            title: text,
            message: text,
            storeAs: z.optional(z.object({ didBlockUser: storeAsKey, didMuteUser: storeAsKey })),
            blockToggle: z.optional(r(blockToggleSchema)),
            muteToggle: z.optional(r(muteToggleSchema)),
            helpline: z.optional(r(helplineSchema)),
            nextButtonText: text,
            next,
            eyebrow: z.optional(text),
            footerItems: z.optional(r(z.array(r(listItemSchema))))
          })
        ])
        .register(z.globalRegistry, { luauName: 'AnyNode' })
    ),
    submission: z.object({
      target: r(SubmissionTargetSchema),
      data: z.object({
        abuseVector: r(z.string()),
        targetIdStr: r(z.string()),
        category: r(z.string()),
        comment: r(z.string()),
        custom: z.optional(z.record(z.string(), r(z.string()))),
        targetType: z.optional(r(z.string()))
      })
    }),
    attributeSchema: z
      .record(
        z.string(),
        z.object({
          type: z.enum(['string', 'boolean', 'number']),
          required: z.optional(z.boolean()),
          source: z.optional(z.literal('caller'))
        })
      )
      .register(z.globalRegistry, { luauName: 'AttributeSchema' })
  });
};

/**
 * Fields injected by the backend server before sending to the client.
 * Not present in template configs, but present in Hydrated and Resolved schemas.
 */
const serverFields = {
  attributes: z.record(z.string(), z.union([z.string(), z.boolean(), z.number()])),
  translations: z.record(z.string(), z.string())
};

/** Validator for template config files (resolver statements allowed, no server-injected fields). */
export const TemplateConfigSchema = createConfigSchema(true);

/** Validator for hydrated config from the backend (resolver statements + server-injected fields). */
export const HydratedConfigSchema = z.object({
  ...createConfigSchema(true).shape,
  ...serverFields
});

/** Validator for resolved config (all resolvers resolved, all server fields present). */
export const ResolvedConfigSchema = z.object({
  ...createConfigSchema(false).shape,
  ...serverFields
});

/** The template config type (no server fields, may contain resolver statements). */
export type TemplateConfig = z.infer<typeof TemplateConfigSchema>;

/** The hydrated config type from the backend (server fields + resolver statements). */
export type HydratedConfig = z.infer<typeof HydratedConfigSchema>;

/** The fully resolved config type (no resolver statements, all server fields present). */
export type ResolvedConfig = z.infer<typeof ResolvedConfigSchema>;

/** Validator for any single resolved node (union of all node types). */
export const ResolvedNodeSchema = ResolvedConfigSchema.shape.nodes.def.valueType;

/** Validator for any single hydrated node (union of all node types, with resolvers). */
export const HydratedNodeSchema = HydratedConfigSchema.shape.nodes.def.valueType;

/** The hydrated node type from the backend (server fields + resolver statements). */
export type HydratedNode = z.infer<typeof HydratedNodeSchema>;

export type ResolvedNode = z.infer<typeof ResolvedNodeSchema>;

export type HydratedListItem = HydratedConfig['resources'][string]['value'][number];

export type ResolvedListItem = ResolvedConfig['resources'][string]['value'][number];
